```cpp
// aim_probe.cpp — cl.exe /EHsc /std:c++17 aim_probe.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <cmath>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static uintptr_t ModBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (_wcsicmp(me.szModule, mod) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

template<typename T>
static bool RPM(HANDLE h, uintptr_t addr, T& out) {
    SIZE_T got = 0;
    return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &got) && got == sizeof(T);
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = (argc > 1) ? argv[1] : L"[进程名]";
    const wchar_t* mod  = (argc > 2) ? argv[2] : L"[模块名]";   // 如 Game.exe / libil2cpp.so 同名模块

    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"pid not found: %s\n", proc); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 2; }

    uintptr_t base = ModBase(pid, mod);
    wprintf(L"pid=%lu base=%s%p\n", pid, L"0x", (void*)base);

    // 1) 客户端世界根指针：UWorld / GWorld 常见形态
    //    [模块名 + [偏移1] + 偏移2] ...
    uintptr_t p1 = 0;
    if (RPM(h, base + [偏移1], p1) && p1)
        wprintf(L"p1=%p\n", (void*)p1);

    // 2) 本地玩家实体 + 相机/视图矩阵（W2S 用）
    //    矩阵通常 float[16] / float[4][4]，行主序
    float vm[16]{};
    if (RPM(h, base + [视图矩阵偏移], vm))
        wprintf(L"vm[0]=%f vm[15]=%f\n", vm[0], vm[15]);

    CloseHandle(h);
    return 0;
}
```

