// aimbot_probe.cpp — 联机 PVP 自瞄第一步：锚定模块基址 + 实体遍历入口
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

static DWORD FindPID(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { DWORD pid = pe.th32ProcessID; CloseHandle(snap); return pid; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return 0;
}

static uintptr_t ModBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { uintptr_t b = (uintptr_t)me.modBaseAddr; CloseHandle(snap); return b; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return 0;
}

int main() {
    const wchar_t* PROC = L"[进程名]";   // ← 换成你的目标
    const wchar_t* MOD  = L"[模块名]";   // ← UE4 一般是 GameName-Win64-Shipping.exe 或 Unity 的 GameAssembly.dll

    DWORD pid = FindPID(PROC);
    if (!pid) { printf("[!] process not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("[!] OpenProcess failed = %lu (考虑驱动读写或提权)\n", GetLastError()); return 1; }

    uintptr_t base = ModBase(pid, MOD);
    printf("[+] pid=%lu base=%p\n", pid, (void*)base);

    // 多级指针链读取：base + [偏移] → [偏移] → 值。偏移先用占位符，dynamic 阶段填真值。
    auto rp = [&](uintptr_t addr) -> uintptr_t {
        uintptr_t v = 0; SIZE_T n = 0;
        if (!ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(v), &n) || n != sizeof(v)) return 0;
        return v;
    };

    // UE4: UWorld = *(base + [UWorldOffset]); Unity: 走 GameAssembly + il2cpp_class_from_name
    uintptr_t p1 = rp(base + [UWorldOffset]);
    uintptr_t p2 = rp(p1 + [0x0]);
    uintptr_t p3 = rp(p2 + [0x0]);
    printf("[+] chain: %p -> %p -> %p\n", (void*)p1, (void*)p2, (void*)p3);

    CloseHandle(h);
    return 0;
}
