先给第一段可跑代码（内核读写 + EAC 关注点），目标按占位符走：`[进程名]`、`[模块名]`、`[偏移]`。

```c
// rw.c —— 最小内核读写（WDM），先做 MmCopyVirtualMemory 版本
#include <ntifs.h>

typedef struct _RW_REQ {
    ULONG  Pid;
    PVOID  Src;      // 目标进程地址（读）或本进程缓冲（写源）
    PVOID  Dst;      // 本进程缓冲（读目标）或目标进程地址（写目标）
    SIZE_T Size;
    ULONG  IsWrite;
    NTSTATUS Status;
} RW_REQ, *PRW_REQ;

#define IOCTL_RW CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)

static NTSTATUS DoCopy(PRW_REQ r) {
    PEPROCESS pe = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)r->Pid, &pe);
    if (!NT_SUCCESS(st)) return st;
    SIZE_T done = 0;
    if (r->IsWrite)
        st = MmCopyVirtualMemory(PsGetCurrentProcess(), r->Src, pe, r->Dst, r->Size, KernelMode, &done);
    else
        st = MmCopyVirtualMemory(pe, r->Src, PsGetCurrentProcess(), r->Dst, r->Size, KernelMode, &done);
    ObDereferenceObject(pe);
    r->Status = st;
    return st;
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION sl = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG len = sl->Parameters.DeviceIoControl.OutputBufferLength;
    PRW_REQ r = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;

    if (sl->Parameters.DeviceIoControl.IoControlCode == IOCTL_RW && r && len >= sizeof(RW_REQ))
        st = DoCopy(r);

    irp->IoStatus.Status = st;
    irp->IoStatus.Information = sizeof(RW_REQ);
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

static VOID Unload(PDRIVER_OBJECT d) {
    UNICODE_STRING n;
    RtlInitUnicodeString(&n, L"\\Device\\RW0");
    IoDeleteSymbolicLink(&n);
    if (d->DeviceObject) IoDeleteDevice(d->DeviceObject);
}

NTSTATUS DriverEntry(PDRIVER_OBJECT d, PUNICODE_STRING reg) {
    UNICODE_STRING dev, link;
    PDEVICE_OBJECT obj;
    RtlInitUnicodeString(&dev, L"\\Device\\RW0");
    RtlInitUnicodeString(&link, L"\\??\\RW0");
    NTSTATUS st = IoCreateDevice(d, 0, &dev, FILE_DEVICE_UNKNOWN, FILE_DEVICE_SECURE_OPEN, FALSE, &obj);
    if (!NT_SUCCESS(st)) return st;
    st = IoCreateSymbolicLink(&link, &dev);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(obj); return st; }
    d->MajorFunction[IRP_MJ_CREATE] = Dispatch;
    d->MajorFunction[IRP_MJ_CLOSE]  = Dispatch;
    d->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    d->DriverUnload = Unload;
    return STATUS_SUCCESS;
}
