```c
// eac_rw.sys —— WDM 驱动骨架，目标进程由 IOCTL 传入 PID
#include <ntifs.h>

#define DEV_NAME  L"\\Device\\EacRw"
#define SYM_NAME  L"\\DosDevices\\EacRw"
#define IOCTL_READ   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQ {
    ULONG   Pid;
    PVOID   RemoteAddr;
    PVOID   LocalBuf;     // 用户态缓冲，内核侧 Probe 后使用
    SIZE_T  Size;
} RW_REQ, *PRW_REQ;

static NTSTATUS DoReadWrite(PRW_REQ req, BOOLEAN bWrite)
{
    PEPROCESS proc = NULL;
    NTSTATUS  st;
    SIZE_T    done = 0;
    if (!req || req->Size == 0 || req->Size > 0x100000) return STATUS_INVALID_PARAMETER;
    st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc);
    if (!NT_SUCCESS(st)) return st;
    __try {
        ProbeForRead(req->LocalBuf, req->Size, 1);
        if (bWrite) {
            st = MmCopyVirtualMemory(PsGetCurrentProcess(), req->LocalBuf,
                                     proc, req->RemoteAddr, req->Size, KernelMode, &done);
        } else {
            st = MmCopyVirtualMemory(proc, req->RemoteAddr,
                                     PsGetCurrentProcess(), req->LocalBuf, req->Size, KernelMode, &done);
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) { st = STATUS_ACCESS_VIOLATION; }
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp)
{
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG    code = sp->Parameters.DeviceIoControl.IoControlCode;
    PVOID    buf  = irp->AssociatedIrp.SystemBuffer;
    if (buf && sp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQ)) {
        if (code == IOCTL_READ)  st = DoReadWrite((PRW_REQ)buf, FALSE);
        if (code == IOCTL_WRITE) st = DoReadWrite((PRW_REQ)buf, TRUE);
    }
    irp->IoStatus.Status      = st;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    UNICODE_STRING devName, symName;
    PDEVICE_OBJECT dev = NULL;
    NTSTATUS st;
    RtlInitUnicodeString(&devName, DEV_NAME);
    RtlInitUnicodeString(&symName, SYM_NAME);
    st = IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN, FILE_DEVICE_SECURE_OPEN, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;
    IoCreateSymbolicLink(&symName, &devName);
    drv->MajorFunction[IRP_MJ_CREATE]         = Dispatch;
    drv->MajorFunction[IRP_MJ_CLOSE]          = Dispatch;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    drv->DriverUnload = NULL;   // 卸载路径在正式工程里补 DriverUnload
    return STATUS_SUCCESS;
}
```

