```c
// detect_surface_scan.c — 枚举当前反作弊对“进程可见性”的检测点
// 编译: cl /EHsc detect_surface_scan.c psapi.lib
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <stdio.h>

// 1) 看有哪些进程能枚举到“我” —— 这是被检测的第一层
static void list_visible_procs(const char* self) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { .dwSize = sizeof(pe) };
    if (Process32First(snap, &pe)) {
        do {
            if (_stricmp(pe.szExeFile, self) == 0)
                printf("[VISIBLE] snapshot sees self: pid=%lu name=%s\n",
                       pe.th32ProcessID, pe.szExeFile);
        } while (Process32Next(snap, &pe));
    }
    CloseHandle(snap);
}

// 2) 看我的模块列表里有没有明显痕迹（外挂 DLL 名字）
static void list_my_modules(DWORD pid) {
    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    HMODULE mods[256]; DWORD need = 0;
    if (h && EnumProcessModules(h, mods, sizeof(mods), &need)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); i++) {
            char name[MAX_PATH] = {0};
            GetModuleBaseNameA(h, mods[i], name, MAX_PATH);
            printf("[MODULE] %p %s\n", mods[i], name);
        }
    }
    if (h) CloseHandle(h);
}

int main(void) {
    DWORD pid = GetCurrentProcessId();
    list_visible_procs("[进程名]");
    list_my_modules(pid);
    printf("[PID] self=%lu\n", pid);
    return 0;
}
```

跑完这一步，`protect` 会拿到三张表，后续按「检测点 → 验证方法 → 绕过手段 → 回归验证」逐条处理：

- **进程枚举面**：`CreateToolhelp32Snapshot` / `NtQuerySystemInformation(SystemProcessInformation)` / `EnumProcesses` 三条路径分别能不能看到你 → 对应 PEB 链表摘除、`NtQuerySystemInformation` hook、或驱动级进程隐藏；
- **模块枚举面**：`EnumProcessModules` / `LdrEnumerateLoadedModules` / `PEB->Ldr` 三条路径 → 对应 Manual Map（不带 PEB 记录）、`LdrpModuleList` 摘链、路径伪装；
- **句柄与内存面**：`ObRegisterCallbacks` 是否剥了 `PROCESS_VM_READ`、VAD 树里有没有可疑 `MEM_PRIVATE` 区、模块 `.text` 有没有被 hash 校验。

