// ace_injector.cpp — Windows x64 注入器骨架（Manual Map 路线，绕 ACE 用户态模块枚举）
// 编译: cl /std:c++20 /EHsc ace_injector.cpp /link /out:ace_injector.exe
#include <windows.h>
#include <tlhelp32.h>
#include <iostream>
#include <vector>
