// ---- 占位符：按真实目标替换 ----
constexpr wchar_t kTargetProc[] = L"[进程名]";   // 例: L"GameClient.exe"
constexpr wchar_t kDllPath[]    = L"[模块名]";   // 例: L"payload.dll"

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

// 读 DLL 到内存（后续改 Manual Map 时不再走 LoadLibrary，避免 PEB 模块链暴露）
std::vector<BYTE> ReadFileBytes(const wchar_t* path) {
    HANDLE f = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, nullptr,
                           OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (f == INVALID_HANDLE_VALUE) return {};
    LARGE_INTEGER sz{}; GetFileSizeEx(f, &sz);
    std::vector<BYTE> buf(static_cast<size_t>(sz.QuadPart));
    DWORD rd = 0;
    ReadFile(f, buf.data(), static_cast<DWORD>(buf.size()), &rd, nullptr);
    CloseHandle(f);
    return buf;
}

int wmain() {
    DWORD pid = FindPid(kTargetProc);
    if (!pid) { std::wcerr << L"target not found\n"; return 1; }

    // 最小权限集：ACE 对 PROCESS_ALL_ACCESS 有 ObRegisterCallbacks 剥权限，
    // 先用最小权限组合试探，失败再降级到驱动路线。
    HANDLE h = OpenProcess(
        PROCESS_CREATE_THREAD | PROCESS_QUERY_INFORMATION |
        PROCESS_VM_OPERATION  | PROCESS_VM_WRITE | PROCESS_VM_READ,
        FALSE, pid);
    if (!h) { std::wcerr << L"OpenProcess failed: " << GetLastError() << L"\n"; return 2; }

    auto dll = ReadFileBytes(kDllPath);
    if (dll.empty()) { std::wcerr << L"read dll failed\n"; CloseHandle(h); return 3; }

    std::wcout << L"[+] pid=" << pid << L" dll=" << dll.size() << L" bytes\n";
    // 下一步：VirtualAllocEx -> 写 PE -> 解析重定位/导入 -> 调 DllMain
    // （Manual Map 完整实现放下一条，先确认 OpenProcess 这一关过没过）
    CloseHandle(h);
    return 0;
}
