// win_probe.cpp  — cl /std:c++17 /EHsc win_probe.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <vector>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

int wmain() {
    const wchar_t* TARGET = L"[进程名].exe";   // ← 占位
    const wchar_t* MODULE = L"[模块名].exe";   // ← 占位

    DWORD pid = FindPid(TARGET);
    if (!pid) { wprintf(L"pid not found: %s\n", TARGET); return 1; }

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 1; }

    HMODULE mods[1024]; DWORD need = 0;
    if (!EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        wprintf(L"EnumProcessModulesEx failed: %lu\n", GetLastError()); return 1;
    }
    // 枚举全部模块，用于后续静态定位
    for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
        wchar_t path[MAX_PATH]{};
        MODULEINFO mi{};
        GetModuleFileNameExW(h, mods[i], path, MAX_PATH);
        GetModuleInformation(h, mods[i], &mi, sizeof(mi));
        wprintf(L"%p  %8zu  %s\n", mi.lpBaseOfDll, mi.SizeOfImage, path);
    }

    // 目标模块基址
    HMODULE target = GetModuleHandleExW(0, MODULE, nullptr) ? nullptr : nullptr;
    (void)target;
    printf("pid=%lu handle=%p base_lookup_done\n", pid, h);
    // 后续：基址 + [偏移1] + [偏移2] → 实体列表头
    CloseHandle(h);
    return 0;
}
