// ext_read.cpp — 外部进程读写最小骨架 (Windows x64, MSVC x64 Release)
// 编译: cl /O2 /EHsc ext_read.cpp /link user32.lib
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <cstdint>
#include <vector>
#include <string>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static uint64_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W me{ sizeof(me) };
    uint64_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, mod) == 0) { base = (uint64_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

// 多级指针链解析: base + offsets[0] -> deref -> +offsets[1] -> deref ... -> 最终地址
static uint64_t ResolveChain(HANDLE h, uint64_t base, const std::vector<uint64_t>& offs) {
    uint64_t addr = base;
    for (size_t i = 0; i < offs.size(); ++i) {
        addr += offs[i];
        if (i + 1 == offs.size()) break;      // 最后一级不回读，得到字段地址
        uint64_t next = 0;
        if (!ReadProcessMemory(h, (LPCVOID)addr, &next, sizeof(next), nullptr)) return 0;
        if (!next) return 0;
        addr = next;
    }
    return addr;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* exe    = L"[进程名].exe";
    const wchar_t* module = L"[模块名].exe";
    // 占位符: 真实偏移必须来自 dynamic 角色的运行时验证，不要猜
    std::vector<uint64_t> chain = { 0x[基址偏移], 0x[一级偏移], 0x[二级偏移], 0x[字段偏移] };

    DWORD pid = FindPid(exe);
    if (!pid) { wprintf(L"pid not found\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION,
                           FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed %lu\n", GetLastError()); return 1; }

    uint64_t base = GetModuleBase(pid, module);
    wprintf(L"pid=%lu base=0x%llx\n", pid, (unsigned long long)base);
    if (!base) { CloseHandle(h); return 1; }

    uint64_t field = ResolveChain(h, base, chain);
    wprintf(L"field=0x%llx\n", (unsigned long long)field);

    if (field) {
        int32_t val = 0;
        SIZE_T n = 0;
        if (ReadProcessMemory(h, (LPCVOID)field, &val, sizeof(val), &n)) {
            wprintf(L"value=%d\n", val);
        } else {
            wprintf(L"RPM failed %lu\n", GetLastError());
        }
    }
    CloseHandle(h);
    return 0;
}
