```cpp
// target_scan.cpp — 模块基址 + 多级指针链定位骨架
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

// 占位符：按实际目标替换
const wchar_t* PROC_NAME = L"[进程名].exe";
const wchar_t* MOD_NAME  = L"[模块名].dll";

DWORD GetPid(const wchar_t* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(h, &pe); ok; ok = Process32NextW(h, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(h); return pe.th32ProcessID; }
    CloseHandle(h); return 0;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(h, &me); ok; ok = Module32NextW(h, &me))
        if (!_wcsicmp(me.szModule, mod)) { CloseHandle(h); return (uintptr_t)me.modBaseAddr; }
    CloseHandle(h); return 0;
}

bool Read(HANDLE p, uintptr_t addr, void* buf, size_t n) {
    SIZE_T got;
    return ReadProcessMemory(p, (LPCVOID)addr, buf, n, &got) && got == n;
}

// 多级指针链解析：offsets[0] 是模块基址偏移，后续依次解引用
uintptr_t ResolveChain(HANDLE p, uintptr_t base, const std::vector<uintptr_t>& offs) {
    uintptr_t addr = base + offs[0];
    for (size_t i = 1; i < offs.size(); ++i) {
        uintptr_t next = 0;
        if (!Read(p, addr, &next, sizeof(next)) || !next) return 0;
        addr = next + offs[i];
    }
    return addr;
}

int main() {
    DWORD pid = GetPid(PROC_NAME);
    if (!pid) { printf("pid not found\n"); return 1; }
    HANDLE p = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!p) { printf("OpenProcess failed %lu\n", GetLastError()); return 1; }
    uintptr_t base = GetModuleBase(pid, MOD_NAME);
    printf("pid=%lu base=%p\n", pid, (void*)base);

    // 示例偏移表：全占位，需用 CE / x64dbg 实测后替换
    std::vector<uintptr_t> chain = { 0x[一层偏移], 0x[二层偏移], 0x[三层偏移] };
    uintptr_t finalAddr = ResolveChain(p, base, chain);
    printf("final addr = %p\n", (void*)finalAddr);

    if (finalAddr) {
        int val = 0;              // 先 dump 原值
        if (Read(p, finalAddr, &val, sizeof(val)))
            printf("原始值 = %d (0x%X)\n", val, val);
    }
    CloseHandle(p);
    return 0;
}
