#include <psapi.h>
#include <stdio.h>
#include <vector>
#include <string>

// [进程名] 换成真实进程名，例如 L"Game.exe"
static const wchar_t* TARGET = L"[进程名]";

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

int wmain() {
    DWORD pid = GetPid(TARGET);
    if (!pid) { wprintf(L"[-] 没找到 %ls\n", TARGET); return 1; }
    wprintf(L"[+] PID = %lu\n", pid);

    // 先 OpenProcess 拿句柄；被反作弊剥权限时改走内核驱动（后面派 protect 出）
    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { wprintf(L"[-] OpenProcess 失败: %lu\n", GetLastError()); return 2; }

    // 枚举模块 + 基址
    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        DWORD n = need / sizeof(HMODULE);
        for (DWORD i = 0; i < n; i++) {
            wchar_t path[MAX_PATH]{};
            MODULEINFO mi{};
            GetModuleFileNameExW(h, mods[i], path, MAX_PATH);
            GetModuleInformation(h, mods[i], &mi, sizeof(mi));
            wprintf(L"  base=%p size=0x%lX  %ls\n",
                    mi.lpBaseOfDll, mi.SizeOfImage, path);
        }
    }
    CloseHandle(h);
    return 0;
}
