// aim_base.cpp — 编译: cl /std:c++17 /EHsc aim_base.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

// ===== 占位符，逆向出来后替换 =====
static const wchar_t* TARGET_PROC = L"[进程名].exe";   // 例: L"GameClient.exe"
static const wchar_t* TARGET_MOD  = L"[模块名].exe";   // 例: L"GameClient.exe" 或 L"GameCore.dll"

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

uintptr_t ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, mod) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int main() {
    DWORD pid = FindPid(TARGET_PROC);
    if (!pid) { printf("[!] 进程未找到: %ls\n", TARGET_PROC); return 1; }
    uintptr_t base = ModuleBase(pid, TARGET_MOD);
    printf("[+] pid = %lu\n[+] %ls base = 0x%llX\n", pid, TARGET_MOD, (unsigned long long)base);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("[!] OpenProcess fail = %lu\n", GetLastError()); return 1; }  // 被句柄保护挡住 → 走 protect 角色出驱动路径
    printf("[+] handle ok\n");
    CloseHandle(h);
    return 0;
}
```

跑通这一步说明：进程找到了、模块基址拿到了、句柄权限够（如果 `OpenProcess` 返回 5 = 被 `ObRegisterCallbacks` 剥了权限，这时候得走内核读写，后面再切）。

